      // 忽略 userId 为 0 或 null 的情况\n        if (orderQuery.getUserId() != null && orderQuery.getUserId() != 0) {\n            queryWrapper.eq(Order::getUserId, orderQuery.getUserId());\n        }\n\n        // 忽略 productId 为 0 或 null 的情况\n        if (orderQuery.getProductId() != null && orderQuery.getProductId() != 0) {\n            queryWrapper.eq(Order::getProductId, orderQuery.getProductId());\n        }\n\n        // 忽略 orderStatus 为 0 或 null 的情况\n        if (orderQuery.getOrderStatus() != null && orderQuery.getOrderStatus() != 0) {\n            queryWrapper.eq(Order::getOrderStatus, orderQuery.getOrderStatus());\n        }\n\n        // 忽略 paymentStatus 为 0 或 null 的情况\n        if (orderQuery.getPaymentStatus() != null && orderQuery.getPaymentStatus() != 0) {\n            queryWrapper.eq(Order::getPaymentStatus, orderQuery.getPaymentStatus());\n        }\n\n        // 忽略 startTime 为 null 的情况\n        if (orderQuery.getStartTime() != null) {\n            queryWrapper.ge(Order::getCreatedAt, orderQuery.getStartTime());\n        }\n\n        // 忽略 endTime 为 null 的情况\n        if (orderQuery.getEndTime() != null) {\n            queryWrapper.le(Order::getCreatedAt, orderQuery.getEndTime());\n        }\n\n        // 忽略 minPrice 为 0 或 null 的情况\n        if (orderQuery.getMinPrice() != null && orderQuery.getMinPrice().compareTo(BigDecimal.ZERO) != 0) {\n            queryWrapper.ge(Order::getTotalPrice, orderQuery.getMinPrice());\n        }\n\n        // 忽略 maxPrice 为 0 或 null 的情况\n        if (orderQuery.getMaxPrice() != null && orderQuery.getMaxPrice().compareTo(BigDecimal.ZERO) != 0) {\n            queryWrapper.le(Order::getTotalPrice, orderQuery.getMaxPrice());\n        }\n\n        // 分页查询\n        return this.page(new Page<>(orderQuery.getPage(), orderQuery.getSize()), queryWrapper);\n    }\n}\n"})}),"\n",(0,a.jsxs)(n.p,{children:["封装查询参数：",(0,a.jsx)(n.code,{children:"OrderQuery"})]}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-java",children:'